PRAGMA foreign_keys = ON;

UPDATE notifications
SET created_at = printf('2026-06-%02dT%02d:%02d:00+08:00', 1 + ((CAST(substr(notification_id, -3) AS INTEGER)) % 28), 7 + (CAST(substr(notification_id, -3) AS INTEGER) % 11), CAST(substr(notification_id, -3) AS INTEGER) % 60),
    title = CASE (CAST(substr(notification_id, -3) AS INTEGER) % 15)
      WHEN 0 THEN 'pre-class hydration personal reminder' WHEN 1 THEN 'midday short-walk prompt' WHEN 2 THEN 'game-record organization completion reminder'
      WHEN 3 THEN 'eyes-closed rest after evening class' WHEN 4 THEN 'classroomlightingreview' WHEN 5 THEN 'between-classscapular movement'
      WHEN 6 THEN 'weekendmeal window' WHEN 7 THEN 'dataupreviewoffscreenpromptshow' WHEN 8 THEN 'privatepersoncalendarconflictcheck'
      WHEN 9 THEN 'health recordmissingreview' WHEN 10 THEN 'parent-email authorization boundary' WHEN 11 THEN 'classlocationchangedataverify'
      WHEN 12 THEN 'distinguish step sources' WHEN 13 THEN 'neck stiffness self-report' ELSE 'eye fatigue self-report' END,
    body =
      CASE (CAST(substr(notification_id, -3) AS INTEGER) % 15)
        WHEN 0 THEN 'Hydrate before the next class; do not use training to crowd out meals.' WHEN 1 THEN 'ifhasthreearrivefivescoredataairarchive,candatadatadatawalking.'
        WHEN 2 THEN 'completedpaperrecordorganizeorganizeafteroffopenhead-downdatadata.' WHEN 3 THEN 'eveningclassendafterdatacloseeyeanddatadatadatadata.'
        WHEN 4 THEN 'confirmedafterarrangelightingisdatadatareview,dataneedtimedatadataplace.' WHEN 5 THEN 'between-classdatalowcandatascapularaftercompress,notforcedataneck.'
        WHEN 6 THEN 'Keep lunch during long classes; do not teach continuously to the end.' WHEN 7 THEN 'Do screen review in segments with distance gaze after each segment.'
        WHEN 8 THEN 'onlyconditionorganizepersonal reminder,notdatachangeGo Academyformalclass.' WHEN 9 THEN 'Mark missing values as missing; do not estimate completion.'
        WHEN 10 THEN 'Without user authorization, do not disclose health information to parents.' WHEN 11 THEN 'Refresh classroom and time in the calendar before execution.'
        WHEN 12 THEN 'Record work movement and intentional walking separately.' WHEN 13 THEN 'recordstiffstiffscoreandcontinuetime,no diagnosis.'
        ELSE 'recordeye fatiguescorewithscreen/Go boardexposurebackgroundcontext.' END
      || ' '
      || CASE CAST((CAST(substr(notification_id, -3) AS INTEGER)) / 15 AS INTEGER)
        WHEN 0 THEN 'status completed.' WHEN 1 THEN 'statusread.' WHEN 2 THEN 'Historically skipped once.' WHEN 3 THEN 'Historically rescheduled due to class conflict.'
        WHEN 4 THEN 'Historically changed to rest due to fatigue.' WHEN 5 THEN 'Historically device data was complete.' WHEN 6 THEN 'Historically device data was partially missing.'
        WHEN 7 THEN 'Historically recorded self-report only.' WHEN 8 THEN 'Historically consistent with the personal calendar.' WHEN 9 THEN 'Historically no external email was needed.'
        WHEN 10 THEN 'Historically no purchase was involved.' WHEN 11 THEN 'Historically no equipment was used.' WHEN 12 THEN 'Historically retained the next review.'
        WHEN 13 THEN 'Historically closed risk.' ELSE 'for natural retrieval only.' END,
    payload_json = json_object('kind','historical_personal_reminder','source_context',source,'personal_only',1)
WHERE notification_id LIKE 'ntf_gt_noise_%';

-- Persist each reminder's actual topic, time and source in structured form;
-- repeated technical payload shells do not count as separate business facts.
UPDATE notifications
SET payload_json = json_object(
      'kind','historical_personal_reminder',
      'topic',title,
      'source_context',source,
      'recorded_at',created_at,
      'personal_only',1,
      'completion_context',body)
WHERE notification_id LIKE 'ntf_gt_noise_%';

UPDATE notifications
SET notification_id = replace(notification_id, 'ntf_gt_noise_', 'ntf_gt_archive_')
WHERE notification_id LIKE 'ntf_gt_noise_%';
